    super('YouTube authorization could not be started.');
    this.code = code === 'STATE_LIMIT_REACHED' ? 'STATE_LIMIT_REACHED' : 'STATE_BEGIN_OUTCOME_UNKNOWN';
    this.status = this.code === 'STATE_LIMIT_REACHED' ? 'begin_limit_reached' : 'begin_outcome_unknown';
